import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import RiskList from './pages/RiskList';
import RiskForm from './pages/RiskForm';
import Layout from './components/Layout';

const ProtectedRoute = ({ children, showBackButton = false, backButtonText = 'Back to Dashboard' }) => {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div style={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '100vh',
        flexDirection: 'column',
        gap: '1rem'
      }}>
        <div style={{ 
          width: '48px', 
          height: '48px', 
          border: '4px solid #e5e7eb',
          borderTopColor: '#3b82f6',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite'
        }} />
        <p style={{ color: '#6b7280' }}>Loading...</p>
        <style>{`
          @keyframes spin {
            to { transform: rotate(360deg); }
          }
        `}</style>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/login" />;
  }

  return (
    <Layout showBackButton={showBackButton} backButtonText={backButtonText}>
      {children}
    </Layout>
  );
};

const AppRoutes = () => {
  const { user } = useAuth();

  return (
    <Routes>
      <Route path="/login" element={user ? <Navigate to="/" /> : <Login />} />

      <Route path="/" element={
        <ProtectedRoute>
          <Dashboard />
        </ProtectedRoute>
      } />

       <Route path="/risks" element={
         <ProtectedRoute>
           <RiskList key={Date.now()} />
         </ProtectedRoute>
       } />

      <Route path="/risks/new" element={
        <ProtectedRoute showBackButton={true} backButtonText="Back to Risk Register">
          <RiskForm />
        </ProtectedRoute>
      } />

      <Route path="/risks/:id" element={
        <ProtectedRoute showBackButton={true} backButtonText="Back to Risk Register">
          <RiskForm />
        </ProtectedRoute>
      } />

      <Route path="/risks/:id/edit" element={
        <ProtectedRoute showBackButton={true} backButtonText="Back to Risk Register">
          <RiskForm />
        </ProtectedRoute>
      } />

      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
};

const App = () => {
  return (
    <AuthProvider>
      <Router>
        <AppRoutes />
      </Router>
    </AuthProvider>
  );
};

export default App;
